(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["el"] = {"ui":{"skip":"Μετάβαση στο περιεχόμενο","back":"← Πίσω στο AI-gile","lang.button":"Γλώσσα: {name}","lang.dialog":"Διάλεξε γλώσσα","lang.search":"Αναζήτηση γλωσσών","lang.none":"Καμία γλώσσα δεν ταιριάζει","lang.notYet":"Το {name} δεν έχει μεταφραστεί ακόμα","theme.aria":"Εναλλαγή μεταξύ φωτεινού και σκούρου θέματος","theme.toLight":"Αλλαγή σε φωτεινό θέμα","theme.toDark":"Αλλαγή σε σκούρο θέμα","index.title":"AI-gile: η ομάδα ανάπτυξης με AI, σε έναν πίνακα","index.description":"Το AI-gile είναι ένας πίνακας kanban για ομάδες προγραμματισμού με AI. Δουλεύουν όσο κοιμάσαι· εσύ παίρνεις μία μικρή στοίβα με πράγματα να αποφασίσεις, να δοκιμάσεις και να εγκρίνεις.","hero.logoAlt":"Εικονίδιο του πίνακα AI-gile","hero.h1.html":"Η ομάδα ανάπτυξης με AI, σε έναν&nbsp;πίνακα.","hero.alpha":"🐣 Κλειστή pre-alpha","hero.alphaTitle":"Πρώιμο και ημιτελές: ευχαριστούμε που το δοκιμάζεις!","hero.lede":"Χτίζουν όσο κοιμάσαι. Ξυπνάς σε μία μικρή στοίβα: μερικές ερωτήσεις, μερικά πράγματα να δοκιμάσεις, ένα-δυο μωβ διαμάντια. Κλικ, έγκριση και πίσω στον καφέ σου.","dl.windows":"Εφαρμογή για Windows","dl.browser":"Τρέξε το στον browser","dl.soon":"Σύντομα","dl.notify":"🔔 Ειδοποίησέ με όταν ανοίξει","dl.notifySmall":"Alpha ή beta","hero.secondary":"Agile, αλλά η ομάδα δεν χρειάζεται ποτέ καφέ για stand-up. (Κάνει stand-up ούτως ή άλλως.)","pitch.h2":"Το AI-gile σε όσες λέξεις θέλεις","pitch.lede":"Διάλεξε μήκος, από μία λέξη έως 144. Κάθε μήκος είναι η δική του περιγραφή, γραμμένη για αυτό το μέγεθος. Σύρε το ρυθμιστικό ή χρησιμοποίησε τα βέλη του πληκτρολογίου.","pitch.rangeLabel":"Μήκος σε λέξεις","pitch.dice":"🎲 άλλη εκδοχή","pitch.words.one":"{n} λέξη","pitch.words.other":"{n} λέξεις","pitch.letters.one":"{n} γράμμα","pitch.letters.other":"{n} γράμματα","pitch.chars.one":"{n} χαρακτήρας","pitch.chars.other":"{n} χαρακτήρες","count.line.html.one":"{n} κάρτα στον πίνακα αυτή τη στιγμή","count.line.html.other":"{n} κάρτες στον πίνακα αυτή τη στιγμή","features.aria":"Τι κάνει","f.pile.h":"Μία στοίβα για σένα","f.pile.html":"Το <b>Για σένα</b> μαζεύει ό,τι σε περιμένει, από όλα τα έργα: ερωτήσεις, πράγματα να δοκιμάσεις, εργασίες που μπορεί να κάνει μόνο άνθρωπος. Η ουρά σου λέει τι έρχεται και πόση ώρα θα πάρει.","f.sleep.h":"Ομάδες που δουλεύουν όσο κοιμάσαι","f.sleep.p":"Κάθε έργο έχει έναν επικεφαλής και μια ομάδα από πράκτορες AI. Σχολίασε μια κάρτα και η ομάδα ξυπνά, κάνει τη δουλειά και σου την επιστρέφει με βήματα που μπορεί να ακολουθήσει ένας κουρασμένος άνθρωπος.","f.tester.h":"Πρώτα ελέγχει ένας tester AI","f.tester.p":"Πριν φτάσει οτιδήποτε σε σένα, ένας tester ακολουθεί τα βήματα σε ένα αντίγραφο της εφαρμογής και δείχνει τι είδε, με στιγμιότυπο οθόνης. Ξεφύλλισε όσα πέρασαν και έγκρινε με ένα κλικ.","f.proof.h":"Αποδείξεις, όχι υποσχέσεις","f.proof.p":"Κάθε παράδοση δείχνει τι άλλαξε: τα αρχεία, το diff, τα στιγμιότυπα. Δεν χρειάζεται να ανοίγεις κάθε εφαρμογή για να δεις αν τελείωσε.","f.chat.h":"Κουβέντα με τους επικεφαλής σου","f.chat.p":"Μια πλευρική στήλη σαν του Discord: ένα εικονίδιο ανά έργο, μωβ διαμάντια για ό,τι σε χρειάζεται. Στείλε μια ιδέα σε έναν επικεφαλής· την κάνει κάρτες και σχέδιο, με ένα κουμπί ✅ Πάμε.","f.tidy.h":"Συγυρίζει μόνο του","f.tidy.p":"Οι σχετικές κάρτες ενώνονται σε μία, οι μπερδεμένοι τίτλοι διορθώνονται και ένας έλεγχος tokens κρατά τον κώδικα λιτό. Λιγότερα πράγματα να εναλλάσσεις, λιγότερα να σκέφτεσαι.","f.private.h":"Δικό σου, στον υπολογιστή σου","f.private.li1":"Ο πίνακας τρέχει στο δικό σου μηχάνημα και απαντά μόνο σε σένα.","f.private.li2":"Τα ιδιωτικά μηνύματα μεταξύ ανθρώπων είναι κρυπτογραφημένα από άκρο σε άκρο.","f.private.li3":"Χωρίς λογαριασμούς, χωρίς trackers, χωρίς cookies.","f.lang.h":"Στη γλώσσα σου","f.lang.p":"Πάνω από 120 γλώσσες, από ολλανδικά, ουαλικά και ιαπωνικά μέχρι πειρατικά, Γιόδα και κλίνγκον, με γρήγορη επιστροφή στα αγγλικά για τους όρους των developers.","tl.aria":"Χρονολόγιο από την πρώτη κουβέντα μέχρι τον οδικό χάρτη","tl.h2":"Από την πρώτη κουβέντα μέχρι το τι ακολουθεί","tl.lede":"Πραγματικές ημερομηνίες και ώρες, στη δική σου ζώνη ώρας. Μετά το σήμερα είναι το σχέδιο, χωρίς υποσχέσεις για ημερομηνίες.","tl.today":"Σήμερα","tl.planned":"προγραμματισμένο","tl.cards.one":"{n} κάρτα","tl.cards.other":"{n} κάρτες","join.h2":"Έλα κι εσύ","join.lede":"Το AI-gile το φτιάχνει ένας μικρός άνθρωπος και ένας μεγάλος αριθμός υπομονετικών πρακτόρων. Προς το παρόν είναι ιδιωτικό, σε κλειστό alpha με φίλους. Θες να το δοκιμάσεις όταν ανοίξει;","join.btn":"Δήλωσε ενδιαφέρον","join.small":"Θα σου στείλουμε email, τίποτα άλλο","footer.tag":"AI-gile. Χωρίς trackers, χωρίς cookies, χωρίς καφέ για stand-up.","footer.licence":"Επαγγελματική άδεια","footer.status":"Κατάσταση","form.sending":"Αποστολή…","form.failed":"Δεν πέτυχε: δοκίμασε ξανά αργότερα.","form.offline":"Δεν βρέθηκε σύνδεση με το AI-gile: δοκίμασε ξανά αργότερα.","interest.title":"AI-gile: ειδοποίησέ με όταν ανοίξει το alpha","interest.description":"Άφησε το email σου για να μάθεις πότε ανοίγει το κλειστό alpha ή beta του AI-gile.","interest.h1":"🔔 Ειδοποίησέ με όταν ανοίξει","interest.lede":"Το AI-gile είναι σε κλειστό pre-alpha. Άφησε το email σου και θα σου γράψουμε μία φορά, όταν υπάρχει θέση για σένα.","interest.email":"Το email σου","interest.which":"Ποια δοκιμή;","interest.alpha":"Κλειστό alpha: πρώιμο, ακατέργαστο, πολλές αλλαγές","interest.beta":"Beta: σταθερότερο, αργότερα","interest.both":"Όποιο, ό,τι έρθει πρώτο","interest.submit":"Βάλε με στη λίστα","interest.thanks":"Ευχαριστούμε! Είσαι στη λίστα.","licence.title":"AI-gile: επαγγελματική άδεια","licence.description":"Χρησιμοποιείς το AI-gile στην επιχείρησή σου; Ζήτησε δωρεάν επαγγελματική άδεια.","licence.h1":"📜 Επαγγελματική άδεια","licence.lede":"Χρησιμοποιείς το AI-gile στη δουλειά; Πες μας ποιος είσαι και τι κάνεις. Αν κάνει κάποιο καλό, η άδεια είναι δωρεάν.","licence.company":"Εταιρεία","licence.website":"Ιστότοπος","licence.what":"Τι κάνεις","licence.how":"Πώς βοηθά τον κόσμο","licence.email":"Email","licence.submit":"Αίτηση","licence.thanks":"Ευχαριστούμε! Θα απαντήσουμε με email.","status.title":"Κατάσταση του AI-gile","status.h1":"Κατάσταση του AI-gile","status.quiet":"Όλα ήσυχα","status.checking":"Έλεγχος…","status.offline":"Δεν είναι δυνατή η σύνδεση με την υπηρεσία κατάστασης αυτή τη στιγμή (νέα προσπάθεια)","status.updated":"ενημερώθηκε {ago}","status.justNow":"μόλις τώρα","status.min":"πριν από {n} λεπ.","status.hours":"πριν από {n} ώ.","status.days":"πριν από {n} ημ.","live.h2":"Δες το να χτίζεται, ζωντανά","live.caption":"Κάθε κάρτα είναι κρυφή: βλέπεις το σχήμα της δουλειάς, όχι τις λέξεις.","live.watching.one":"ζωντανά: {n} παρακολουθεί","live.watching.other":"ζωντανά: {n} παρακολουθούν","live.offline":"Ο ζωντανός πίνακας παίρνει μια μικρή ανάσα. Ξαναπέρασε σύντομα.","live.cols":"Backlog|Προς υλοποίηση|Σε εξέλιξη|Η ομάδα ελέγχει|Για test από σένα|Για την ομάδα|Ολοκληρώθηκε","live.last.now":"Η τελευταία κάρτα μετακινήθηκε μόλις τώρα","live.last.min.one":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} λεπτό","live.last.min.other":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} λεπτά","live.last.hour.one":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} ώρα","live.last.hour.other":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} ώρες","live.last.day.one":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} ημέρα","live.last.day.other":"Η τελευταία κάρτα μετακινήθηκε πριν από {n} ημέρες"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Ρομπότ.","Ανατέθηκε."]},{"n":2,"texts":["Ρομποτικό kanban.","Πράκτορες, οργανωμένοι.","Ιδέες, υλοποιημένες."]},{"n":3,"texts":["Kanban για ρομπότ.","Ιδέες γίνονται λειτουργίες.","Δωρεάν kanban πρακτόρων."]},{"n":5,"texts":["Πίνακας kanban που δουλεύουν πράκτορες.","Γράφεις κάρτες. Χτίζουν οι πράκτορες.","Δωρεάν, τοπικό, δοκιμασμένο, λίγο τρελό."]},{"n":8,"texts":["Ένας δωρεάν πίνακας kanban όπου δουλεύουν πράκτορες AI.","Γράψε μια ιδέα. Οι πράκτορες τη χτίζουν. Εσύ εγκρίνεις.","Agile για έναν άνθρωπο και πολλά υπομονετικά ρομπότ."]},{"n":13,"texts":["Ένας πίνακας kanban στον υπολογιστή σου, όπου πράκτορες AI παίρνουν τις κάρτες και τις υλοποιούν.","Γράψε μια ιδέα. Μια ομάδα πρακτόρων τη χτίζει. Ένας tester την ελέγχει. Εσύ λες ναι.","Δωρεάν, χωρίς λογαριασμούς και trackers: ένας πίνακας, μερικά ρομπότ, κι εσύ υπεύθυνος."]},{"n":21,"texts":["Το AI-gile είναι ένας πίνακας kanban για δουλειά με πράκτορες προγραμματισμού AI. Εκείνοι παίρνουν τις κάρτες· εσύ τις δοκιμάζεις και τις εγκρίνεις.","Κάθε έργο αποκτά έναν επικεφαλής και μια ομάδα πρακτόρων AI. Σχολίασε οποιαδήποτε κάρτα και η ομάδα πιάνει αμέσως δουλειά.","Ένας δωρεάν προσωπικός πίνακας εργασιών που τρέχει στον δικό σου υπολογιστή. Οι εργάτες είναι ρομπότ. Αυτός που λέει ναι είσαι εσύ."]},{"n":34,"texts":["Βάζεις ιδέες σε έναν πίνακα. Μια ομάδα πρακτόρων AI τις κάνει λειτουργίες που δουλεύουν, τις δοκιμάζει και σου τις επιστρέφει με βήματα για να τις δοκιμάσεις. Τίποτα δεν θεωρείται έτοιμο, αν δεν το πεις εσύ.","Το AI-gile είναι ένας σπιτικός πίνακας kanban που έφτιαξε ο Rich με πολλή βοήθεια από τους πράκτορες που τώρα διαχειρίζεται. Είναι δωρεάν, τρέχει στον υπολογιστή σου και μοιράζεται με φίλους, δεν πουλιέται.","Φαντάσου έναν κανονικό πίνακα kanban, με στήλες από το Backlog μέχρι το Ολοκληρώθηκε, μόνο που τις κάρτες τις παίρνουν πράκτορες AI. Αναφέρουν πρόοδο, ρωτούν όταν κολλήσουν και περιμένουν πάντα το δικό σου οκέι."]},{"n":55,"texts":["Το AI-gile είναι ένας πίνακας kanban όπου η ομάδα αποτελείται από πράκτορες AI. Κάθε έργο έχει έναν επικεφαλής που σχεδιάζει τη δουλειά και βοηθούς που την υλοποιούν. Όταν μια λειτουργία είναι έτοιμη, ένας tester AI τη δοκιμάζει και τραβά ένα στιγμιότυπο, και μετά καταλήγει στη στοίβα σου. Έγκρινέ την ή σχολίασε και την ξαναδουλεύουν.","Ξεκίνησε ως ο τρόπος ενός ανθρώπου να παρακολουθεί πολλές συνεδρίες προγραμματισμού με AI ταυτόχρονα και μεγάλωσε σε έναν κανονικό πίνακα. Τρέχει στο μηχάνημά σου, δεν θέλει λογαριασμό και δεν έχει trackers. Είναι δωρεάν για φίλους και περίεργους. Είναι και ημιτελές, οπότε περίμενε τραχιές άκρες και καμιά έκπληξη.","Να η ειλικρινής εκδοχή. Τις ιδέες πρέπει ακόμα να τις έχεις εσύ, και τα αποτελέσματα πρέπει ακόμα να τα ελέγχεις εσύ. Ό,τι υπάρχει ανάμεσα το κάνει το AI-gile: κρατά τις κάρτες σε τάξη, ξυπνά τον σωστό πράκτορα όταν σχολιάζεις, δείχνει ακριβώς τι άλλαξε και τα βάζει όλα σε μία μικρή στοίβα για σένα."]},{"n":89,"texts":["Το AI-gile είναι ένας δωρεάν πίνακας kanban που τρέχεις στον δικό σου υπολογιστή. Αντί για ανθρώπους, κάθε έργο έχει μια ομάδα πρακτόρων AI: έναν επικεφαλής που μετατρέπει τις ιδέες σου σε κάρτες και σχέδιο, και βοηθούς που παίρνουν τις κάρτες με σειρά προτεραιότητας. Όταν κάτι χτιστεί, ένας tester AI ακολουθεί τα βήματα δοκιμής και σου δείχνει τι είδε. Μετά περιμένει σε μία στοίβα με όνομα Για σένα. Το εγκρίνεις ή σχολιάζεις και η ομάδα ξαναπροσπαθεί. Τίποτα δεν φτάνει ποτέ στο Ολοκληρώθηκε χωρίς εσένα.","Μερικά πράγματα που ίσως δεν περιμένεις. Μια νυχτερινή φρουρά κρατά γεμάτη τη στήλη Προς υλοποίηση όσο κοιμάσαι, διαλέγοντας κάρτες που δεν χρειάζονται απάντηση από σένα. Ένας μετρητής tokens δείχνει πόσα χρησιμοποίησαν οι πράκτορες σήμερα και αυτή την εβδομάδα, και η λειτουργία Χωρίς tokens τους λέει να σταματήσουν να ξοδεύουν. Μπορείς να στέλνεις μηνύματα σε φίλους, και τα ιδιωτικά μηνύματα είναι κρυπτογραφημένα από άκρο σε άκρο. Ο πίνακας μιλά περίπου 120 γλώσσες, μεταξύ τους ολλανδικά, φλαμανδικά, πειρατικά και κλίνγκον. Τίποτα από αυτά δεν κοστίζει ούτε ένα λεπτό, και κανείς δεν προσπαθεί να στα πουλήσει.","Το AI-gile είναι ένα μικρό προσωπικό project, όχι εταιρεία. Ο Rich ήθελε να φροντίζει πολλά έργα προγραμματισμού με AI χωρίς να ανοίγει κάθε εφαρμογή για να τα ελέγχει, κι έτσι αυτός και οι πράκτορες έφτιαξαν έναν πίνακα γι' αυτό και μετά τον χρησιμοποίησαν για να φτιάξουν τα υπόλοιπα του ίδιου. Είναι σε κλειστό pre-alpha, που σημαίνει ότι δουλεύει, ως επί το πλείστον, για μια χούφτα φίλους. Δεν υπάρχει σελίδα τιμών, ούτε ενημερωτικό δελτίο, ούτε σχέδιο ανάπτυξης. Αν σου ακούγεται χρήσιμο, μπορείς να ζητήσεις να το δοκιμάσεις όταν ανοίξει λίγο περισσότερο."]},{"n":144,"texts":["Το AI-gile είναι ένας πίνακας kanban για έναν άνθρωπο και πολλούς πράκτορες AI. Τρέχει στον δικό σου υπολογιστή και είναι εντελώς δωρεάν. Προσθέτεις έργα, και κάθε έργο αποκτά έναν επικεφαλής και μια μικρή ομάδα. Συνομιλείς με τον επικεφαλής, κάτι σαν στο Discord, και περιγράφεις μια ιδέα· εκείνος τη μετατρέπει σε κάρτες και σχέδιο και περιμένει να πατήσεις Πάμε. Η ομάδα δουλεύει τις κάρτες με σειρά προτεραιότητας, χρησιμοποιώντας μια απλή γραμμή εντολών φτιαγμένη για γλωσσικά μοντέλα. Πριν επιστρέψει οτιδήποτε σε σένα, ένας tester AI ακολουθεί τα βήματα σε ένα αντίγραφο της εφαρμογής και επισυνάπτει ένα στιγμιότυπο οθόνης. Η ολοκληρωμένη δουλειά καταλήγει στη στοίβα σου με τα αρχεία που άλλαξαν και το diff. Την εγκρίνεις ή αφήνεις ένα σχόλιο και η ομάδα ξυπνά και προσπαθεί ξανά. Μόνο εσύ μπορείς να μετακινήσεις μια κάρτα στο Ολοκληρώθηκε.","Μια μέρα με το AI-gile, χονδρικά. Το βράδυ αφήνεις μερικά σχόλια: αυτό το κουμπί είναι σε λάθος σημείο, εκείνη η λίστα να ταξινομείται, μπορούμε να έχουμε σκούρο θέμα; Πας για ύπνο. Οι πράκτορες διαβάζουν τα σχόλια, κάνουν τις αλλαγές, τις δοκιμάζουν και σου τις επιστρέφουν. Αν το Προς υλοποίηση αδειάσει, η νυχτερινή φρουρά το γεμίζει από το backlog με κάρτες που δεν χρειάζονται απάντηση από σένα. Το πρωί υπάρχει μία μικρή στοίβα: μερικές ερωτήσεις και μερικά πράγματα να δοκιμάσεις, το καθένα με βήματα που μπορεί να ακολουθήσει ένας νυσταγμένος άνθρωπος και ένα στιγμιότυπο που δείχνει ότι δουλεύει. Περνάς από πάνω τους, εγκρίνεις τα καλά και στέλνεις πίσω τα υπόλοιπα. Ένας μετρητής tokens δείχνει τι χρησιμοποιήθηκε, και η λειτουργία Χωρίς tokens υπάρχει για τις φτωχές εβδομάδες. Μετά πας για πρωινό, κάτι στο οποίο οι πράκτορες δεν μπορούν ακόμα να βοηθήσουν.","Πρώτα, τι δεν είναι το AI-gile. Δεν είναι startup, δεν πουλιέται και κανείς δεν μαζεύει τα δεδομένα σου. Είναι ένας δωρεάν πίνακας που τρέχει στον υπολογιστή σου, χωρίς λογαριασμούς, χωρίς trackers και χωρίς cookies. Τι είναι: ένα τακτοποιημένο μέρος για να βλέπεις όλα τα έργα προγραμματισμού με AI μαζί, με μια ομάδα πρακτόρων να κάνει τις κάρτες και εσένα να παίρνεις τις αποφάσεις. Ενώνει τις σχετικές κάρτες, διορθώνει τους μπερδεμένους τίτλους και προσέχει πόσο λιτός μένει ο κώδικας. Μιλά περίπου 120 γλώσσες, από ολλανδικά και φλαμανδικά μέχρι πειρατικά και κλίνγκον. Οι φίλοι μπορούν να στέλνουν μηνύματα ο ένας στον άλλον, ιδιωτικά και κρυπτογραφημένα. Το έφτιαξαν ο Rich και πάρα πολλοί υπομονετικοί πράκτορες, ως επί το πλείστον χρησιμοποιώντας το ίδιο. Είναι σε κλειστό pre-alpha, οπότε σε κάποια σημεία είναι ακατέργαστο. Αν σου ακούγεται διασκεδαστικό, ζήτα το ευγενικά και ίσως μπεις νωρίς."]}],"quips":{"1":"Μία λέξη. Τολμηρή. Ίσως υπερβολικά τολμηρή.","3":"Τρεις λέξεις. Ήδη πιο ειλικρινείς από τις περισσότερες σελίδες προϊόντων.","8":"Οκτώ λέξεις. Και πάλι πιο σύντομες από ένα stand-up.","21":"Τα μήκη, παρεμπιπτόντως, είναι story points. Φυσικά και είναι.","55":"Πενήντα πέντε λέξεις. Δύο κάρτες ολοκληρώθηκαν όσο το διάβαζες.","144":"Αυτή ήταν η μεγάλη. Δεν υπάρχει 233. Οι πράκτορες πήγαν για ύπνο."}},"timeline":{"first-idea.name":"Η πρώτη ιδέα","first-idea.line":"Η πρώτη κουβέντα, πριν υπάρξει καθόλου κώδικας.","first-board.name":"Ο πρώτος πίνακας","first-board.line":"Ένας πίνακας που παρακολουθεί τη δική του κατασκευή: κάρτες, στήλες, σύρσιμο και απόθεση, έργα.","team-roles.name":"Ομάδα και ρόλοι","team-roles.line":"Προφίλ πρακτόρων, πρότυπα ομάδων, χώροι και ποιος κάνει τι.","install.name":"Εγκατάσταση και εκδόσεις","install.line":"Ένα zip που μπορεί να εγκαταστήσει ένας φίλος, αυτόματες ενημερώσεις, κανάλια και επαναφορά.","usage-saver.name":"Εξοικονόμηση χρήσης","usage-saver.line":"Μέτρηση του κόστους των εκτελέσεων, λιτός κώδικας, προστασία του ορίου σου.","friends.name":"Φίλοι και κοινή χρήση","friends.line":"Ιδιωτικά μηνύματα, κρυπτογραφημένος αναμεταδότης, προσκλήσεις, ρόλοι και κοινά έργα.","languages.name":"Γλώσσες","languages.line":"Κάθε κείμενο οθόνης σε αρχείο γλώσσας, με τα ολλανδικά και τα φλαμανδικά πρώτα.","ai-tester.name":"Tester AI","ai-tester.line":"Ένας tester ελέγχει πρώτα κάθε παράδοση και δείχνει τι είδε.","website.name":"Ο ιστότοπος","website.line":"Το aigile.lol, η προεπισκόπηση και αυτό το χρονολόγιο.","streaming.name":"Συνομιλία και streaming","streaming.line":"Discord, Twitch, OBS, λειτουργία streamer, GIF και emoji.","no-ai.name":"Έκδοση χωρίς AI","no-ai.line":"Ένας πίνακας για όσους προγραμματίζουν χωρίς AI, και δημόσιοι πίνακες.","night-watch.name":"Νυχτερινή φρουρά","night-watch.line":"Ένας φρουρός και ένας Scrum Master κρατούν τις ομάδες στη δουλειά όσο κοιμάσαι.","p-more.name":"Όλα τα υπόλοιπα","p-more.line":"Μικρότερες ιδέες που περιμένουν ακόμα τη σειρά τους.","p-android.name":"Κινητό και Android","p-android.line":"Πρόσβαση στον πίνακά σου από το κινητό και μετά εγγενής εφαρμογή Android.","p-release.name":"Alpha και πέρα","p-release.line":"Κλειστό alpha, ο ζωντανός ιστότοπος και μετά το beta.","p-languages.name":"Περισσότερες γλώσσες","p-languages.line":"Πάνω από εκατό γλώσσες και λειτουργία εμβύθισης για όσους μαθαίνουν.","p-engines.name":"Περισσότερες μηχανές AI","p-engines.line":"Διάλεξε Claude, Codex ή Gemini για κάθε πράκτορα.","p-pro.name":"Επαγγελματική πρακτική","p-pro.line":"Ετικέτες ρίσκου, πύλες συγχώνευσης, κάρτες συμβάντων και προστατευτικά κιγκλιδώματα.","p-self.name":"Φροντίδα για σένα","p-self.line":"Λειτουργία κούρασης, υπενθυμίσεις αυτοφροντίδας και 4:20.","p-servers.name":"Διακομιστές και κλίμακα","p-servers.line":"Καθολικές ρυθμίσεις διακομιστή, ρόλοι και σχεδιασμός για ανάπτυξη.","p-livestream.name":"Έξτρα streaming","p-livestream.line":"Συνομιλία Twitch, προσαρμοσμένα emoji και δημόσια ζωντανή προβολή."},"words":{"button":"📖 Όροι προγραμματισμού","h":"📖 Οι όροι προγραμματισμού με απλά λόγια","intro":"Οι όροι που χρησιμοποιούν οι προγραμματιστές (και οι ομάδες AI), με απλά λόγια.","search":"Αναζήτηση λέξης…","none":"Καμία λέξη δεν ταιριάζει.","close":"Κλείσιμο","list":[{"id":"backlog","word":"Backlog","text":"Ιδέες και δουλειά που δεν έχουν προγραμματιστεί ακόμα. Κανείς δεν δουλεύει σε αυτά μέχρι να περάσουν στο «Προς υλοποίηση»."},{"id":"sprint","word":"Sprint","text":"Ένα σύντομο διάστημα δουλειάς (συχνά μία ή δύο εβδομάδες) με συμφωνημένο σύνολο καρτών να ολοκληρωθούν.","also":["sprints","σπριντ"]},{"id":"standup","word":"Stand-up","text":"Μια γρήγορη ενημέρωση: τι έκανε κάθε μέλος της ομάδας, τι κάνει μετά και τι το εμποδίζει.","also":["standup","stand-ups","στανταπ"]},{"id":"bug","word":"Bug","text":"Κάτι που δεν δουλεύει όπως πρέπει.","also":["bugs","μπαγκ"]},{"id":"test","word":"Test","text":"Δοκιμή ενός ολοκληρωμένου κομματιού δουλειάς για να δεις ότι κάνει ό,τι ζητήθηκε, πριν το αποδεχτείς.","also":["tests","τεστ","δοκιμή","δοκιμές"],"noTip":1},{"id":"commit","word":"Commit","text":"Ένα αποθηκευμένο στιγμιότυπο του κώδικα, με μια σύντομη σημείωση για το τι άλλαξε. Μπορείς πάντα να γυρίσεις σε ένα.","also":["commits"]},{"id":"push","word":"Push","text":"Αποστολή αποθηκευμένων στιγμιότυπων (commits) από αυτόν τον υπολογιστή στο GitHub, ώστε να έχουν αντίγραφο ασφαλείας και να μοιράζονται."},{"id":"branch","word":"Branch","text":"Μια ξεχωριστή γραμμή δουλειάς στον κώδικα, ώστε να γίνονται αλλαγές χωρίς να αγγίζεται η κύρια έκδοση.","also":["branches","κλάδος","κλάδοι"]},{"id":"merge","word":"Merge","text":"Συγχώνευση των αλλαγών ενός branch πίσω στην κύρια έκδοση."},{"id":"repo","word":"Repo","text":"Ο φάκελος του έργου με τον κώδικα και το πλήρες ιστορικό των commits του, συνήθως φυλαγμένος και στο GitHub.","also":["repository","αποθετήριο"]},{"id":"refactor","word":"Refactor","text":"Τακτοποίηση του κώδικα χωρίς να αλλάξει αυτό που κάνει: μικρότερα αρχεία, πιο καθαρά ονόματα, λιγότερη επανάληψη."},{"id":"deploy","word":"Deploy","text":"Η διάθεση μιας νέας έκδοσης σε λειτουργία, π.χ. σε έναν διακομιστή όπου τη χρησιμοποιούν άνθρωποι."},{"id":"kanban","word":"Kanban","text":"Ένας πίνακας με στήλες (Προς υλοποίηση, Σε εξέλιξη, Ολοκληρώθηκε) όπου οι κάρτες κινούνται από αριστερά προς τα δεξιά όσο προχωρά η δουλειά."},{"id":"wip","word":"Όριο WIP","text":"Work in progress: ο μέγιστος αριθμός καρτών σε μια στήλη, ώστε η ομάδα να τελειώνει πράγματα πριν ξεκινήσει άλλα.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Αίτημα να ελεγχθούν και να συγχωνευθούν οι αλλαγές ενός branch στην κύρια έκδοση.","also":["PR"]},{"id":"hook","word":"Hook","text":"Μια μικρή εντολή που τρέχει μόνη της σε συγκεκριμένη στιγμή, π.χ. όταν ξεκινά μια συνεδρία AI, ώστε η ομάδα να ακούει τα σχόλιά σου.","also":["hooks"]},{"id":"token","word":"Token","text":"Η μονάδα με την οποία μετριέται η χρήση του AI: περίπου μερικά γράμματα κειμένου που διαβάστηκαν ή γράφτηκαν. Λιγότερα tokens, περισσότερο πλάνο που απομένει.","also":["tokens"]},{"id":"agent","word":"Πράκτορας","text":"Ένα AI που δουλεύει μόνο του σε μια εργασία: διαβάζει τον κώδικα, κάνει αλλαγές, τρέχει ελέγχους και αναφέρει τα αποτελέσματα.","also":["agent","agents","πράκτορες"]}]}};
